  def test_generated_csharp_comments
    [
      "// <auto-generated/>\nclass C {}",
      "// <autogenerated>\nclass C {}",
      "\n \t// License\n// <auto-generated>\r\nclass C {}",
      "/* License */\n/*\n * <autogenerated>\n */\nclass C {}",
      "/// <auto-generated>\nclass C {}",
      "/** <autogenerated> */\nclass C {}",
      "\xEF\xBB\xBF// <auto-generated>\nclass C {}",
      "#nullable enable\n// <auto-generated>\nclass C {}",
      "// License\n" * 100 + "// <auto-generated>\nclass C {}",
      "/* <auto-generated"
    ].each do |content|
      assert Generated.generated?("src/Code.cs", content), content.inspect
      assert Generated.generated?("src/Code.CS", content.b), content.inspect
    end
  end

  def test_non_generated_csharp
    [
      "",
      "class C {}",
      "// <Auto-Generated>\nclass C {}",
      "// auto-generated\nclass C {}",
      "class C {}\n// <auto-generated>",
      "/* License */ class C {} // <autogenerated>",
      'class C { string s = "<auto-generated>"; }',
      '[System.CodeDom.Compiler.GeneratedCode("tool", "1")] class C {}',
      "#region <auto-generated>\nclass C {}",
      "#if false\n// <auto-generated>\n#endif\nclass C {}",
      "# if DEBUG\n/* <autogenerated> */\n#endif\nclass C {}"
    ].each do |content|
      refute Generated.generated?("src/Code.cs", content), content.inspect
    end

    [
      "src/Code.generated.csx",
      "src/Code.g.i.cs.txt",
      "src/NotTemporaryGeneratedFile_Code.cs",
      "src/TemporaryGeneratedFile_/Code.cs",
      "src/Code.generated.cs/Code.cs",
      "src/Codegenerated.cs",
      "src/Code.gi.cs"
    ].each do |filename|
      refute Generated.generated?(filename, ""), filename
    end

    refute Generated.generated?("src/Code.js", "// <auto-generated>\nclass C {}")
  end

