  def test_generated_vb_comments
    [
      "' <auto-generated/>\nClass C\nEnd Class",
      "' <autogenerated>\nClass C\nEnd Class",
      "\n \t' License\n' <auto-generated>\r\nClass C\nEnd Class",
      "''' <auto-generated>\nClass C\nEnd Class",
      "REM <auto-generated>\nClass C\nEnd Class",
      "rem <autogenerated>\nClass C\nEnd Class",
      "ReM\t<auto-generated>\nClass C\nEnd Class",
      "\xEF\xBB\xBF' <auto-generated>\nClass C\nEnd Class",
      "#Region \"Code\"\n' <auto-generated>\nClass C\nEnd Class",
      "' License\n" * 100 + "' <auto-generated>\nClass C\nEnd Class"
    ].each do |content|
      assert Generated.generated?("src/Code.vb", content), content.inspect
      assert Generated.generated?("src/Code.VB", content.b), content.inspect
    end
  end

  def test_non_generated_vb
    [
      "",
      "Class C\nEnd Class",
      "' <Auto-Generated>\nClass C\nEnd Class",
      "' auto-generated\nClass C\nEnd Class",
      "Class C\nEnd Class\n' <auto-generated>",
      "Dim s As String = \"<auto-generated>\"",
      "Remember = \"<auto-generated>\"",
      "<System.CodeDom.Compiler.GeneratedCode(\"tool\", \"1\")> Class C\nEnd Class",
      "#Region \"<auto-generated>\"\nClass C\nEnd Class",
      "#If False Then\n' <auto-generated>\n#End If\nClass C\nEnd Class",
      "# If DEBUG Then\nREM <autogenerated>\n#End If\nClass C\nEnd Class",
      "// <auto-generated>\nClass C\nEnd Class",
      "/* <auto-generated> */\nClass C\nEnd Class"
    ].each do |content|
      refute Generated.generated?("src/Code.vb", content), content.inspect
    end

    [
      "src/Code.generated.vbx",
      "src/Code.g.i.vb.txt",
      "src/NotTemporaryGeneratedFile_Code.vb",
      "src/TemporaryGeneratedFile_/Code.vb",
      "src/Code.generated.vb/Code.vb",
      "src/Codegenerated.vb",
      "src/Code.gi.vb"
    ].each do |filename|
      refute Generated.generated?(filename, ""), filename
    end

    refute Generated.generated?("src/Code.cs", "' <auto-generated>\nclass C {}")
    refute Generated.generated?("src/Code.cs", "REM <auto-generated>\nclass C {}")
  end
